(() => {
  const data = window.NET_DEMO;
  const navItems = [
    ['dashboard','⌂','看板'],['records','▤','病情整理'],['profile','◉','我的瘤·分级与基因'],['metrics','⌁','双线随访·指标系列'],['onechart','⌖','病情一图秀'],['injection','◷','注射与周期'],['trials','✧','临床研究'],['nutrition','♧','腹泻与饮食'],['wellbeing','♡','慢病心晴'],['questions','☷','就诊问题清单'],['saved','☆','收藏回顾']
  ];
  const main = document.getElementById('main');
  const nav = document.getElementById('nav');
  let currentPage='dashboard';
  let trialView='trialProfile';
  const chartState = { range: 'all', selected: new Set(['cga','h5hiaa']), showValues: true, showGrid: true, pin: null };
  const metricEntries = data.metricSeries.flatMap(series => series.metrics.map(metric => ({ ...metric, seriesId: series.id, seriesTitle: series.title, color: series.color || metric.color })));
  const esc = (s='') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const dateMonth = (label, latestYear) => {
    const parts=String(label).split('-').map(Number);
    if(parts.length===2&&parts[0]>1900)return parts[0]*12+parts[1];
    const month=parts.length===2?parts[0]:1;
    const year=parts.length===2&&parts[0]>12?parts[0]:latestYear;
    return year*12+month;
  };
  const svg = (metric, small=false, range='all') => {
    const allValues=metric.values;
    const allDates=metric.dates;
    const latestLabel=allDates.at(-1)||'';
    const latestParts=String(latestLabel).split('-').map(Number);
    const latestYear=latestParts[0]>1900?latestParts[0]:2026;
    const latestMonth=dateMonth(latestLabel,latestYear);
    const months=({'3m':3,'6m':6,'12m':12}[range]||0);
    const recent=allDates.map((date,i)=>({date,value:allValues[i],index:i})).filter(point=>!months||dateMonth(point.date,latestYear)>=latestMonth-months+1);
    const pointsData=recent.length?recent:[{date:allDates.at(-1),value:allValues.at(-1),index:allValues.length-1}];
    const w=small?240:620,h=small?74:300,pad=small?8:34;
    const lo=Math.min(...allValues),hi=Math.max(...allValues),span=hi-lo||Math.max(Math.abs(hi)*.08,1);
    const pts=pointsData.map((point,i)=>[pad+(pointsData.length===1?0:i*(w-2*pad)/(pointsData.length-1)),h-pad-(point.value-lo)/span*(h-2*pad)]);
    const path=pts.length>1?smoothPath(pts):'';
    const pin=chartState.pin?.id===metric.id?chartState.pin:null;
    const y=pin?pts[pointsData.findIndex(point=>point.index===pin.index)]?.[1]:null;
    const x=pin?pts[pointsData.findIndex(point=>point.index===pin.index)]?.[0]:null;
    return `<svg class="chart ${small?'spark':''}" data-metric="${esc(metric.id)}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(metric.name)}趋势，独立按全期范围缩放"><path class="chart-grid ${chartState.showGrid?'':'is-hidden'}" d="M${pad} ${h/2}H${w-pad}"/><path class="chart-line" d="${path}"/>${pts.map((point,i)=>`<circle class="chart-point${pointsData[i].index===pin?.index?' is-pinned':''}" data-point-index="${pointsData[i].index}" data-metric-id="${esc(metric.id)}" cx="${point[0]}" cy="${point[1]}" r="${small?3:5}" tabindex="0" role="button" aria-label="${esc(metric.name)} ${pointsData[i].value} ${esc(metric.unit)} ${esc(pointsData[i].date)}"><title>${esc(metric.name)} · ${pointsData[i].value} ${esc(metric.unit)} · ${esc(pointsData[i].date)}</title></circle>`).join('')}${!small&&chartState.showValues?`<text x="${pts.at(-1)[0]}" y="${Math.max(15,pts.at(-1)[1]-10)}" text-anchor="end" class="chart-end-value">${esc(pointsData.at(-1).value)} ${esc(metric.unit)}</text><text x="${pad}" y="${h-5}" class="chart-label">${esc(pointsData[0].date)}</text><text x="${w-pad}" y="${h-5}" text-anchor="end" class="chart-label">${esc(pointsData.at(-1).date)}</text>`:''}${x!==null&&y!==undefined?`<circle class="chart-pin-ring" cx="${x}" cy="${y}" r="10"/>`:''}</svg>`;
  };
  const metricDelta = metric => {
    if(metric.values.length<2)return {symbol:'—',text:'暂无前次记录',tone:'flat'};
    const delta=metric.values.at(-1)-metric.values.at(-2);
    return {symbol:delta>0?'↑':delta<0?'↓':'→',text:`${Math.abs(delta).toFixed(metric.precision??(Number.isInteger(delta)?0:1))} ${metric.unit}`,tone:delta>0?'up':delta<0?'down':'flat'};
  };
  const pointSource = (metric,index=chartState.pin?.index) => metric.sources?.[index] || metric.source || `模拟报告记录 ${metric.dates[index]||''} · 来源详情待接入`;
  const renderChart = () => {
    const plot=document.getElementById('oneChartPlot');
    if(!plot)return;
    const selected=metricEntries.filter(metric=>chartState.selected.has(metric.id));
    const legend=selected.map(metric=>`<div class="chart-legend-item"><span class="legend-dot" style="--series-color:${metric.color}"></span><span>${esc(metric.short)}</span><small>${Math.min(...metric.values)}–${Math.max(...metric.values)} ${esc(metric.unit)}（全期）</small></div>`).join('');
    plot.innerHTML=`<div class="chart-legend">${legend||'<span class="muted">尚未选择指标</span>'}</div><div class="trend-stack">${selected.map(metric=>`<section class="trend-row"><div class="trend-label"><span class="legend-dot" style="--series-color:${metric.color}"></span><strong>${esc(metric.short)}</strong><small>${esc(metric.name)} · ${Math.min(...metric.values)}–${Math.max(...metric.values)} ${esc(metric.unit)}</small></div>${svg(metric,false,chartState.range)}</section>`).join('')||'<div class="empty-state">请选择至少一项指标查看趋势。</div>'}</div>${chartState.pin?(()=>{const metric=metricEntries.find(item=>item.id===chartState.pin.id),value=metric?.values[chartState.pin.index],date=metric?.dates[chartState.pin.index];return metric?`<aside class="chart-pin"><button class="pin-close" data-chart-action="clear-pin" aria-label="关闭固定详情">×</button><strong>${esc(metric.name)}</strong><span>${esc(value)} ${esc(metric.unit)} · ${esc(date)}</span><small>来源：${esc(pointSource(metric))}</small></aside>`:''})():''}`;
    wireChartEvents();
  };
  const wireChartEvents = () => {
    const plot=document.getElementById('oneChartPlot');
    if(!plot)return;
    plot.querySelectorAll('.chart-point').forEach(point=>point.addEventListener('click',()=>{chartState.pin={id:point.dataset.metricId,index:Number(point.dataset.pointIndex)};renderChart();}));
    plot.querySelectorAll('.chart-point').forEach(point=>point.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();point.click();}}));
    plot.querySelector('[data-chart-action="clear-pin"]')?.addEventListener('click',()=>{chartState.pin=null;renderChart();});
  };
  // Shape-preserving cubic interpolation (Fritsch–Carlson); no overshoot beyond sampled values.
  function smoothPath(points) {
    if (points.length < 2) return '';
    const n=points.length, d=[], m=[];
    for(let i=0;i<n-1;i++) d.push((points[i+1][1]-points[i][1])/(points[i+1][0]-points[i][0]));
    m[0]=d[0]; m[n-1]=d[n-2];
    for(let i=1;i<n-1;i++) m[i]=d[i-1]*d[i]<=0?0:(d[i-1]+d[i])/2;
    for(let i=0;i<n-1;i++){ if(d[i]===0){m[i]=0;m[i+1]=0;} else { const a=m[i]/d[i],b=m[i+1]/d[i],q=a*a+b*b; if(q>9){const t=3/Math.sqrt(q);m[i]=t*a*d[i];m[i+1]=t*b*d[i];}} }
    let out=`M ${points[0][0]} ${points[0][1]}`;
    for(let i=0;i<n-1;i++){const dx=(points[i+1][0]-points[i][0])/3;out+=` C ${points[i][0]+dx} ${points[i][1]+m[i]*dx} ${points[i+1][0]-dx} ${points[i+1][1]-m[i+1]*dx} ${points[i+1][0]} ${points[i+1][1]}`;}
    return out;
  }
  function setPage(id){
    currentPage=id;
    if(location.hash!==`#${id}`) history.replaceState(null,'',`#${id}`);
    nav.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));
    const item=navItems.find(x=>x[0]===id); document.title=`${item?.[2]||'设置'} · 小泌宝`;
    main.innerHTML=pages[id]?.()||pages.dashboard();
    const pageHead=main.querySelector('.page-head');
    if(pageHead){let actions=pageHead.querySelector('.page-actions');if(!actions){actions=document.createElement('div');actions.className='page-actions';pageHead.appendChild(actions);}const existing=[...pageHead.children].filter(el=>el!==actions);existing.forEach(el=>{if(el.matches('button'))actions.appendChild(el);});if(!actions.querySelector('[data-discuss]')){const discuss=document.createElement('button');discuss.type='button';discuss.className='discuss-btn';discuss.textContent='和 AI 讨论';discuss.setAttribute('data-discuss','');actions.appendChild(discuss);}}
    main.focus({preventScroll:true});
    main.querySelectorAll('[data-discuss]').forEach(button=>button.addEventListener('click',()=>discussCurrentPage()));
    main.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
    main.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>actions[b.dataset.action]?.(b)));
    main.querySelectorAll('[data-trial-nav]').forEach(b=>b.addEventListener('click',()=>{trialView=b.dataset.trialNav;setPage('trials');}));
    main.querySelectorAll('[data-trial-view]').forEach(b=>b.addEventListener('click',()=>{trialView=b.dataset.trialView;setPage('trials');}));
    main.querySelectorAll('[data-trial-action]').forEach(b=>b.addEventListener('click',()=>trialActions[b.dataset.trialAction]?.()));
    main.querySelectorAll('[data-fold]').forEach(d=>d.addEventListener('toggle',()=>{}));
    if(id==='onechart'){
      renderChart();
      main.querySelectorAll('[data-range]').forEach(button=>button.addEventListener('click',()=>{chartState.range=button.dataset.range;main.querySelectorAll('[data-range]').forEach(item=>{const active=item.dataset.range===chartState.range;item.classList.toggle('selected',active);item.setAttribute('aria-pressed',String(active));});renderChart();}));
      main.querySelectorAll('[data-metric-check]').forEach(input=>input.addEventListener('change',()=>{if(input.checked&&chartState.selected.size>=4){input.checked=false;toast('一图秀最多同时显示 4 项指标。');return;}input.checked?chartState.selected.add(input.dataset.metricCheck):chartState.selected.delete(input.dataset.metricCheck);renderChart();}));
      main.querySelectorAll('[data-display]').forEach(input=>input.addEventListener('change',()=>{if(input.dataset.display==='values')chartState.showValues=input.checked;if(input.dataset.display==='grid')chartState.showGrid=input.checked;renderChart();}));
    }
  }
  nav.innerHTML=navItems.map(([id,icon,label])=>`<button class="nav-item" data-page="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')+'<div class="nav-divider"></div><button class="nav-item" data-page="settings"><span class="nav-icon">⚙</span><span>设置</span></button>';
  nav.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
  document.querySelectorAll('.topbar [data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
  const seriesCards=()=>data.metricSeries.map(s=>`<section class="series-block"><div class="series-head"><div class="series-icon">${s.icon}</div><div><h3>${s.title}</h3><p>${s.subtitle}</p></div><span class="series-count">${s.metrics.length} 项</span></div><div class="metric-grid">${s.metrics.map(m=>metricCard(m)).join('')}</div></section>`).join('');
  function metricCard(m){const delta=metricDelta(m),count=m.values.length;return `<article class="metric-card" style="--series-color:${m.color}"><button class="metric-card-inner" type="button" aria-label="翻转查看${esc(m.name)}详情" aria-pressed="false"><span class="metric-face metric-front"><span class="metric-card-head"><span class="category-dot" aria-label="${esc(m.category||m.seriesTitle||'指标')}" title="${esc(m.category||m.seriesTitle||'指标')}"></span><span class="metric-category">${esc(m.category||m.seriesTitle||'指标')}</span><span class="metric-count">${count} 次</span></span><span class="metric-current"><strong>${esc(m.latest)}</strong><small>${esc(m.unit)}</small></span><span class="metric-card-name">${esc(m.short)} · ${esc(m.name)}</span><span class="metric-delta ${delta.tone}"><b>${delta.symbol}</b><span>较前次 ${esc(delta.text)}</span></span><span class="metric-card-date">最近记录 ${esc(m.date)}</span><span class="metric-flip-hint">点按查看趋势 ↻</span></span><span class="metric-face metric-back"><span class="metric-card-head"><span class="category-dot"></span><span class="metric-category">${esc(m.short)} · 近 ${count} 次</span><span class="metric-count">${esc(m.unit)}</span></span>${svg(m,true)}<span class="spark-endpoints"><span>${esc(m.values[0])} · ${esc(m.dates[0])}</span><span>${esc(m.values.at(-1))} · ${esc(m.dates.at(-1))}</span></span><span class="metric-back-source">来源：${esc(m.sources?.[m.values.length-1]||m.source||'模拟报告记录；原件来源字段待实现')}</span><span class="metric-flip-hint">点按翻回 ↻</span></span></button></article>`}
  const timeline=()=>data.pathway.map(p=>`<details class="phase-fold"><summary><span class="phase-dot"></span><span class="phase-title">${esc(p.phase)}</span><time>${esc(p.date)}</time><span class="phase-summary">${esc(p.summary)}</span><span class="fold-cue">展开细节</span></summary><div class="phase-detail">${[['方案',p.detail.regimen],['指标和趋势',p.detail.metrics],['影像发现',p.detail.imaging],['副作用总结',p.detail.ae],['心理/营养措施和效果',p.detail.support]].map(([title,block])=>`<section class="pd-block"><h4>${title}</h4><p class="pd-summary">${esc(block.summary)}</p><dl>${block.items.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>`).join('')}</div></details>`).join('');
  /* 36 号 §2.6 · 看板首卡：状态卡四件
     eyebrow（D+N 状态卡 · 距下一事项）／锚点派生大字天数（不手填）／现状行（阶段原文 + 状态 + 下次日期与事项）／出口按钮排。
     无锚点时不显示天数，整卡显示「待初始化」并指向三步向导。 */
  const PROTO_CLOCK = '2026-10-25'; // 原型固定“今天”，与页面 eyebrow 同源，避免日期漂移
  const dayDiff = (from,to)=>Math.round((new Date(`${to}T00:00:00`)-new Date(`${from}T00:00:00`))/86400000);
  const statusCard = () => {
    const anchor=data.profile?.diagnosisDate;
    const next=data.next?.[0];
    const phase=data.pathway?.at(-1);
    if(!anchor){
      return `<section class="status-card" aria-labelledby="status-card-title"><p class="status-eyebrow">状态卡 · 待初始化</p><div class="status-main"><div><strong class="status-day pending" id="status-card-title">待初始化</strong><span class="status-anchor">还没有可派生天数的锚点日</span></div><div class="status-now"><span class="status-phase">三步向导</span><span class="status-state">① 连接本机服务　② 记录确诊与分级档案　③ 设定随访锚点日</span><span class="status-next">下次：待初始化后按锚点计算</span></div></div><div class="status-actions"><button class="primary-btn" data-page="profile">开始三步初始化 →</button><button class="soft-btn" type="button" data-primer-open aria-haspopup="dialog" aria-controls="disease-primer" aria-label="疾病概要：神经内分泌肿瘤是什么？">疾病概要：神经内分泌肿瘤是什么？</button></div></section>`;
    }
    const dayN=dayDiff(anchor,PROTO_CLOCK);
    const toNext=next?dayDiff(PROTO_CLOCK,next.date):null;
    return `<section class="status-card" aria-labelledby="status-card-title"><p class="status-eyebrow">D+${dayN} 状态卡 · 距${next?.title||'下次安排'}${toNext==null?'':' '+toNext+' 天'}</p><div class="status-main"><div><strong class="status-day" id="status-card-title">第 ${dayN} 天</strong><span class="status-anchor">锚点：确诊日 ${anchor}（Day 0）· 由数据派生</span></div><div class="status-now"><span class="status-phase">${esc(phase?.phase||'阶段待记录')}</span><span class="status-state">${esc(data.profile.status)}</span><span class="status-next">下次：${esc(next?.date||'待安排')}（${esc(next?.title||'')}${next?.value?' · '+esc(next.value):''}）</span></div></div><div class="status-actions"><button class="primary-btn" data-page="metrics">看双线随访（生化+影像）→</button><button class="soft-btn" type="button" data-primer-open aria-haspopup="dialog" aria-controls="disease-primer" aria-label="疾病概要：神经内分泌肿瘤是什么？">疾病概要：神经内分泌肿瘤是什么？</button></div></section>`;
  };
  const pages={
    dashboard:()=>`<div class="page-head"><div><p class="eyebrow">周日 · 2026 年 10 月 25 日</p><h1>上午好，${esc(data.profile.name)}</h1><p class="lead">先看接下来的安排，也可以记下刚拿到的检查结果。</p></div><button class="primary-btn" data-action="addRecord">＋ 记录一项检查</button></div>${statusCard()}<div class="profile-strip"><div class="profile-avatar">林</div><div><strong>${esc(data.profile.subtype)}</strong><p>${esc(data.profile.grade)}　·　${esc(data.profile.status)}</p></div><button class="text-btn" data-page="profile">查看档案 →</button></div><div class="section-title"><div><h2>接下来</h2><p>按日期整理的个人安排 · 模拟数据</p></div><button class="text-btn" data-page="injection">看完整安排 →</button></div><div class="next-grid">${data.next.map(n=>`<article class="next-card ${n.tone}"><span class="next-icon">${n.icon}</span><div><small>${n.title}</small><strong>${n.value}</strong><span>${n.date}</span></div></article>`).join('')}</div><div class="dashboard-columns"><section class="surface"><div class="section-title compact"><div><h2>指标系列</h2><p>最近记录与趋势入口</p></div><button class="text-btn" data-page="metrics">全部指标 →</button></div>${data.metricSeries.slice(0,2).map(s=>`<div class="mini-series"><strong>${s.title}</strong>${s.metrics.slice(0,2).map(m=>`<div class="mini-metric"><div><span>${m.short}</span><strong>${m.latest} <small>${m.unit}</small></strong></div>${svg(m,true)}</div>`).join('')}</div>`).join('')}</section><section class="surface"><div class="section-title compact"><div><h2>最近整理</h2><p>仅显示本地模拟记录</p></div><button class="text-btn" data-page="saved">查看回顾 →</button></div>${data.notes.map(n=>`<div class="note-row"><time>${n.date}</time><span class="note-kind">${n.kind}</span><p>${n.text}</p></div>`).join('')}<button class="soft-btn wide" data-page="questions">准备下次就诊的问题清单</button></section></div><p class="patient-quote">患者原话（改写占位，非一手访谈）：“我想把最近的检查整理好再去复诊。”</p>`,
    records:()=>`<div class="page-head"><div><p class="eyebrow">资料整理</p><h1>病情整理</h1><p class="lead">把报告放在一起，核对后再保存到档案。</p></div><button class="primary-btn" data-action="addRecord">＋ 添加资料</button></div><div class="callout"><span>✦</span><div><strong>AI 可以先帮你整理成草稿</strong><p>报告原文会保留；每一项都由你核对，确认后才记入档案。</p></div><button class="soft-btn" data-action="draft">试用整理示例</button></div><div class="record-grid"><article class="surface record-card"><span class="record-icon">▧</span><h3>病理与免疫组化</h3><p>Ki-67、分化描述、IHC 标志物</p><span class="record-status">已整理 · 模拟报告</span></article><article class="surface record-card"><span class="record-icon">⌁</span><h3>化验结果</h3><p>CgA、5-HIAA、NSE 等</p><span class="record-status">4 次模拟记录</span></article><article class="surface record-card"><span class="record-icon">▤</span><h3>影像报告</h3><p>CT、MRI、SRI 与报告原文</p><span class="record-status">2 份模拟报告</span></article></div><p class="patient-quote">患者原话（改写占位）：“资料散在好几个医院，我想先整理好带去复诊。”</p>`,
    profile:()=>`<div class="page-head"><div><p class="eyebrow">档案只整理报告，不代替医生判断</p><h1>我的瘤 · 分级与基因</h1><p class="lead">保存报告写了什么、什么时候做的，以及来源。</p></div><button class="primary-btn" data-action="draft">✦ 帮我整理报告</button></div><div class="profile-summary surface"><div class="large-avatar">肽</div><div><p class="eyebrow">模拟病情档案</p><h2>${esc(data.profile.subtype)}</h2><p>确诊记录：${data.profile.diagnosisDate}　·　原发部位：${data.profile.primary}</p></div><span class="demo-badge">模拟资料</span></div><div class="detail-grid"><section class="surface detail-card"><div class="section-title compact"><div><h2>病理与免疫组化</h2><p>数值和分级均照录报告原文</p></div><button class="text-btn" data-action="edit">⋯ 更多</button></div><div class="fact-grid"><div><small>分化描述</small><strong>高分化（报告原文）</strong></div><div><small>分级</small><strong>G2（报告原文）</strong></div><div><small>Ki-67</small><strong>${data.profile.ki67}</strong></div><div><small>标本日期</small><strong>2024-03-12</strong></div></div><div class="source-note">来源：模拟病理报告 · 查看原文　|　分级由医生判读，本工作台不计算分级。</div></section><section class="surface detail-card"><div class="section-title compact"><div><h2>基因检测</h2><p>未测、待出、未检出与 VUS 分开记录</p></div><button class="text-btn" data-action="edit">⋯ 更多</button></div><div class="gene-list"><div><span>MEN1</span><strong class="tag neutral">未测</strong></div><div><span>VHL</span><strong class="tag neutral">待出</strong></div><div><span>RET</span><strong class="tag neutral">报告未记录</strong></div><div><span>其他基因</span><strong class="tag neutral">未测</strong></div></div><div class="source-note">模拟占位，不代表真实患者检测结果。</div></section></div><p class="patient-quote">患者原话（改写占位）：“我想知道报告里这些名词分别写了什么，不希望软件替医生下结论。”</p>`,
    metrics:()=>`<div class="page-head"><div><p class="eyebrow">一次记录 · 多处回顾</p><h1>双线随访 · 指标系列</h1><p class="lead">按报告系列整理时间变化；每次结果保留自己的单位与参考区间。</p></div><button class="primary-btn" data-action="addRecord">＋ 记录一项</button></div><div class="notice"><span>ⓘ</span><p>折线只连接同一指标的数值记录，不作病情判断。参考范围以各次实际报告为准；分类报告不加入数值趋势。</p></div>${seriesCards()}<p class="patient-quote">患者原话（改写占位）：“每次结果都在变，我想把报告放在一起看。”</p>`,
    onechart:()=>`<div class="page-head"><div><p class="eyebrow">独立病情一图秀</p><h1>把检查变化放在一张图里</h1><p class="lead">左侧选时间、挑指标与显示方式；点图上的点可固定查看数值和来源。</p></div></div><section class="onechart-layout"><aside class="onechart-controls surface"><div class="control-group"><h2>时间范围</h2><div class="range-chips">${[['3m','3个月'],['6m','6个月'],['12m','12个月'],['all','全部']].map(([id,label])=>`<button type="button" class="range-chip ${chartState.range===id?'selected':''}" data-range="${id}" aria-pressed="${chartState.range===id}">${label}</button>`).join('')}</div></div><div class="control-group"><h2>指标系列</h2><div class="series-check-groups">${data.metricSeries.map(series=>`<fieldset class="series-check-group"><legend><span class="series-icon">${series.icon}</span>${esc(series.title)}</legend>${series.metrics.map(metric=>`<label class="series-check"><input type="checkbox" data-metric-check="${metric.id}" ${chartState.selected.has(metric.id)?'checked':''}><span class="legend-dot" style="--series-color:${metric.color}"></span><span><strong>${esc(metric.short)}</strong><small>${esc(metric.latest)} ${esc(metric.unit)}</small></span></label>`).join('')}</fieldset>`).join('')}</div><small class="selection-limit">最多同时勾选 4 项；勾选后立即更新图表。</small></div><div class="control-group"><h2>显示</h2><label class="display-toggle"><input type="checkbox" data-display="values" ${chartState.showValues?'checked':''}><span>显示末点数值</span></label><label class="display-toggle"><input type="checkbox" data-display="grid" ${chartState.showGrid?'checked':''}><span>显示参考网格</span></label></div></aside><section class="surface chart-panel"><div class="chart-panel-head"><div><h2>随访趋势</h2><p>各指标独立按自身全期范围缩放，数值不可互相比较。</p></div><span class="tag neutral">模拟数据</span></div><div id="oneChartPlot"></div></section></section><p class="patient-quote">患者原话（改写占位）：“我下次复诊时想把最重要的几项指标一起给医生看。”</p>`,
    injection:()=>`<div class="page-head"><div><p class="eyebrow">治疗记录 · 计划日期需与实际医嘱核对</p><h1>注射与周期</h1><p class="lead">把每次注射、治疗周期和复查安排放在一起。</p></div><button class="primary-btn" data-action="addInjection">＋ 记录注射</button></div><div class="next-grid">${data.next.slice(0,2).map(n=>`<article class="next-card ${n.tone}"><span class="next-icon">${n.icon}</span><div><small>${n.title}</small><strong>${n.value}</strong><span>${n.date}</span></div></article>`).join('')}</div><section class="surface pathway-panel"><div class="section-title"><div><h2>治疗历程</h2><p>默认看概要，点开后查看五块记录 · 模拟数据</p></div><button class="text-btn" data-action="print">打印 / 导出</button></div>${timeline()}</section><section class="surface prrt-card"><div><span class="tag lilac-tag">PRRT · 骨架示意</span><h3>核素治疗周期档案</h3><p>国内可及性与审批信息需随数据包更新。此处仅展示未来记录位置，不代表已提供治疗服务。</p></div><button class="soft-btn" data-action="prrt">查看记录结构</button></section><p class="patient-quote">患者原话（改写占位）：“我想记清每次注射的日期和部位，复查时不用翻聊天记录。”</p>`,
    trials:()=>`<div class="page-head"><div><p class="eyebrow">临床研究 · 当前未查询</p><h1>临床研究</h1><p class="lead">从个人病理/基因档案准备检索条件，再选择协助方式。当前数据源未接入。</p></div></div><nav class="research-subnav" aria-label="临床研究二级页面">${[['trialProfile','个人档案'],['trialCriteria','检索条件'],['trialAssist','检索与协助'],['trialReview','结果核对']].map(([id,label])=>`<button type="button" class="research-tab ${trialView===id?'active':''}" data-trial-view="${id}" aria-current="${trialView===id?'page':'false'}">${label}</button>`).join('')}</nav><div class="research-subpage">${trialSubpages[trialView]()}</div><p class="patient-quote">页面说明：当前档案内容为模拟占位；本地 SQLite 与外部检索均未接入。</p>`,
    nutrition:()=>`<div class="page-head"><div><p class="eyebrow">生活记录 · 以实际体验为主</p><h1>腹泻与饮食</h1><p class="lead">记录今天的饮食、排便和身体感受，方便自己回顾或带去就诊。</p></div><button class="primary-btn" data-action="addSymptom">＋ 记一笔</button></div><div class="notice"><span>ⓘ</span><p>本页不判断症状原因、不提供饮食处方。涉及营养问题可把记录带给医生或营养师讨论。</p></div><div class="symptom-grid"><article class="surface symptom-card"><span class="symptom-icon peach">◌</span><h3>今天的排便感受</h3><p>记录次数、形态或困扰程度（患者自述）</p><button class="soft-btn" data-action="addSymptom">记录今天的感受</button></article><article class="surface symptom-card"><span class="symptom-icon mint">♧</span><h3>饮食与体重</h3><p>记录自己吃了什么、体重如何变化</p><button class="soft-btn" data-action="addSymptom">添加一条记录</button></article></div><p class="patient-quote">患者原话（改写占位，非一手访谈）：“有时吃完就不舒服，我想记下来看看什么时候发生。”</p>`,
    wellbeing:()=>`<div class="page-head"><div><p class="eyebrow">慢病生活与情绪</p><h1>慢病心晴</h1><p class="lead">长期治疗和反复复查可能带来疲惫；这里记录你的感受，不做心理诊断。</p></div><button class="primary-btn" data-action="addMood">＋ 记下心情</button></div><div class="wellbeing-hero surface"><div class="wellbeing-art">☼</div><div><h2>今天的你，感觉怎么样？</h2><p>写一句话也可以。你可以选择只留给自己，或整理成就诊时想说的内容。</p><button class="soft-btn" data-action="addMood">开始记录</button></div></div><div class="mood-options">${['有点累','还不错','担心复查','想找人聊聊'].map(x=>`<button class="mood-chip" data-action="moodChoice">${x}</button>`).join('')}</div><p class="patient-quote">患者原话（改写占位）：“每次复查前我都会紧张，想把担心的事先写下来。”</p>`,
    questions:()=>`<div class="page-head"><div><p class="eyebrow">就诊准备</p><h1>下次想问的问题</h1><p class="lead">从最近记录里整理想问医生的事；所有问题由你决定是否保留。</p></div><button class="primary-btn" data-action="addQuestion">＋ 添加问题</button></div><div class="callout"><span>✦</span><div><strong>根据最近记录整理问题草稿</strong><p>生成后可以逐条编辑、删除或补充，不会自动发送给医生。</p></div><button class="soft-btn" data-action="draftQuestion">生成草稿</button></div><div class="question-list">${['这次 CgA 和上次结果可以直接比较吗？','下一次影像检查的时间需要按什么安排？','最近的腹泻感受需要补充哪些记录？'].map((q,i)=>`<label class="question-row"><input type="checkbox" ${i<2?'checked':''}><span>${q}</span><button class="text-btn" data-action="editQuestion">编辑</button></label>`).join('')}</div><button class="primary-btn" data-action="exportQuestions">导出就诊问题清单</button><p class="patient-quote">患者原话（改写占位）：“见医生时容易忘记问题，我想提前写下来。”</p>`,
    saved:()=>`<div class="page-head"><div><p class="eyebrow">记录回顾</p><h1>收藏回顾</h1><p class="lead">最近新增的资料、指标和关注线索都可以在这里找到。</p></div><button class="soft-btn" data-action="export">导出我的资料</button></div><div class="saved-tabs"><button class="saved-tab active">最近记录</button><button class="saved-tab">关注的研究</button><button class="saved-tab">已导出的资料</button></div><div class="saved-list">${data.notes.map(n=>`<article class="surface saved-row"><span class="saved-icon">${n.kind==='指标记录'?'⌁':n.kind==='就诊问题'?'☷':'◷'}</span><div><small>${n.date} · ${n.kind}</small><p>${n.text}</p></div><button class="text-btn" data-action="correct">改这一条</button></article>`).join('')}</div><p class="patient-quote">患者原话（改写占位）：“上次整理的检查和问题，我希望下次还能很快找到。”</p>`,
    settings:()=>`<div class="page-head"><div><p class="eyebrow">小泌宝设置 · 模拟状态</p><h1>资料与数据设置</h1><p class="lead">管理患者资料位置和参考数据来源。设置更改会先预览，不会自动清理原资料。</p></div></div><section class="surface settings-card"><h2>患者资料目录</h2><div class="setting-row"><div><strong>当前状态</strong><p>本地演示目录 · 模拟数据</p></div><span class="tag neutral">原型模拟</span></div><button class="soft-btn" data-action="folder">选择资料目录</button><p class="setting-help">切换目录不会自动搬移或删除原有资料；正式版本需逐步确认旧资料处理方式。</p></section><section class="surface settings-card"><h2>解析方式</h2><div class="setting-row"><div><strong>本地整理</strong><p>原型只展示交互，不发送任何文件或凭据。</p></div><span class="tag mint-tag">未连接</span></div><button class="soft-btn" data-action="parseMode">查看解析选项</button></section><section class="surface settings-card"><h2>临床与研究数据包</h2><div class="setting-row"><div><strong>本地 NET 试验库</strong><p>尚未生成/加载 SQLite 数据库</p></div><span class="tag peach-tag">未接入</span></div><p class="setting-help">外部来源也尚未连接。未查询时显示“未查过”，不将缺数据伪装成零结果。</p></section><div class="settings-actions"><button class="text-btn" data-action="cancelSettings">取消</button><button class="primary-btn" data-action="saveSettings">保存模拟设置</button></div><p class="patient-quote">设置页原型草案；未接入真实目录、云解析或临床数据包。</p>`
  };
  const trialForm={histology:'胰腺 NET（模拟档案）',differentiation:'高分化（报告原文占位）',ki67:'5.2%（模拟）',ihc:'CgA / Syn（模拟占位）',genes:'MEN1：未测；VHL：待出；RET：未记录',treatment:'SSA 模拟记录；真实治疗线待核对',region:'中国大陆',age:'',status:'招募中/状态未知'};
  const trialSubpages={
    trialProfile:()=>`<section class="surface trial-subpage"><div class="subpage-head"><div><h2>个人档案</h2><p>从个人病理/IHC/基因和治疗档案带入检索条件。只显示已记录状态，不推断适配资格。</p></div><span class="tag neutral">档案来源：模拟资料</span></div><div class="trial-field-grid"><div><span class="field-state present">●</span><div><strong>组织学/原发部位</strong><small>${esc(trialForm.histology)}</small></div></div><div><span class="field-state present">●</span><div><strong>分化描述</strong><small>${esc(trialForm.differentiation)}</small></div></div><div><span class="field-state present">●</span><div><strong>Ki-67 / IHC</strong><small>${esc(trialForm.ki67)} · ${esc(trialForm.ihc)}</small></div></div><div><span class="field-state missing">○</span><div><strong>基因结果</strong><small>${esc(trialForm.genes)}</small></div></div><div><span class="field-state present">●</span><div><strong>既往治疗</strong><small>${esc(trialForm.treatment)}</small></div></div></div><div class="notice"><span>ⓘ</span><p>模拟档案只用于展示字段映射。真实查询前由患者逐项核对报告来源、日期和检测状态；VUS/未测/待出分开保留。</p></div><div class="subpage-actions"><button class="soft-btn" data-trial-nav="trialCriteria">下一步：检索条件 →</button></div></section>`,
    trialCriteria:()=>`<section class="surface trial-subpage"><div class="subpage-head"><div><h2>检索条件</h2><p>这些条件仅用于筛选研究记录，不是医学适配或入组判定。</p></div><span class="tag neutral">尚未查询</span></div><div class="criteria-grid"><label>疾病/组织学<input id="trialHistology" value="${esc(trialForm.histology)}"></label><label>分化描述<input id="trialDifferentiation" value="${esc(trialForm.differentiation)}"></label><label>Ki-67 / IHC<input id="trialIhc" value="${esc(trialForm.ki67+' · '+trialForm.ihc)}"></label><label>基因结果<input id="trialGenes" value="${esc(trialForm.genes)}"></label><label>既往治疗线<input id="trialTreatment" value="${esc(trialForm.treatment)}"></label><label>研究地区<select id="trialRegion"><option>中国大陆</option><option>全球</option><option>患者自行选择</option></select></label><label>年龄（可选）<input id="trialAge" inputmode="numeric" placeholder="不填写则不作为筛选条件"></label><label>研究状态<select id="trialStatus"><option>招募中/状态未知</option><option>招募中</option><option>状态不限</option></select></label></div><div class="notice"><span>ⓘ</span><p>保存的条件与页面摘要不会自动变成病历事实；真实来源未连接时点击查询仍会显示“未能查询”，不会显示模拟结果。</p></div><div class="subpage-actions"><button class="soft-btn" data-trial-nav="trialProfile">← 返回个人档案</button><button class="primary-btn" data-trial-action="saveCriteria">保存本次条件</button><button class="soft-btn" data-trial-nav="trialAssist">下一步：检索与协助 →</button></div></section>`,
    trialAssist:()=>`<section class="surface trial-subpage"><div class="subpage-head"><div><h2>检索与协助</h2><p>选择查询来源；AI 可帮你整理搜索词或解释条件，不替你判断适配资格。</p></div><span class="tag peach-tag">来源未接入</span></div><div class="assist-source-list">${data.trialSources.map(source=>`<label class="assist-source"><input type="checkbox" disabled><span><strong>${esc(source.name)}</strong><small>${esc(source.status)} · ${esc(source.detail)}</small></span></label>`).join('')}</div><div class="assist-options"><button class="soft-btn" data-trial-action="draftSearch">✦ 让 AI 整理检索词</button><button class="primary-btn" data-trial-action="query">发起研究检索</button></div><div class="notice"><span>ⓘ</span><p>本地 SQLite 尚未生成，外部工具尚未接入。本原型不会发起网络请求；点击检索会如实记录失败状态。</p></div><div id="queryFeedback" class="query-feedback" role="status"><strong>未查过</strong><span>还没有执行过查询。本状态不代表没有可了解的研究。</span></div><div class="subpage-actions"><button class="soft-btn" data-trial-nav="trialCriteria">← 返回检索条件</button><button class="soft-btn" data-trial-nav="trialReview">查看结果核对页 →</button></div></section>`,
    trialReview:()=>`<section class="surface trial-subpage"><div class="subpage-head"><div><h2>结果核对</h2><p>真实查询返回后，在此逐项核对来源、状态、条件和匹配依据。</p></div><span class="tag peach-tag">当前无真实结果</span></div><div id="trialResultsState" class="trial-results-state"><span>⌕</span><strong>未查过 · 数据源未接入</strong><p>目前没有可核对的研究结果。不要把此状态理解为“零项试验”或“不适合”。</p></div><div class="result-contract"><h3>每条真实结果应包含</h3><ul><li>来源平台与研究编号</li><li>研究地区、招募状态与最近更新时间</li><li>入组条件原文与原始链接</li><li>哪些档案字段有记录、哪些缺失</li><li>匹配依据和未能判断的项目</li></ul></div><div class="notice"><span>ⓘ</span><p>匹配指数目前没有可验证算法，因此不显示分数。将来若纳入排序，也不能表达入组概率或治疗建议。</p></div><div class="subpage-actions"><button class="soft-btn" data-trial-nav="trialProfile">返回个人档案</button><button class="soft-btn" data-trial-nav="trialAssist">返回检索与协助</button></div></section>`
  };
  const trialActions={
    saveCriteria(){for(const [id,key] of [['trialHistology','histology'],['trialDifferentiation','differentiation'],['trialGenes','genes'],['trialTreatment','treatment'],['trialAge','age'],['trialStatus','status']]){const el=document.getElementById(id);if(el)trialForm[key]=el.value;}const ihc=document.getElementById('trialIhc');if(ihc){const parts=ihc.value.split('·').map(x=>x.trim());trialForm.ki67=parts[0]||'';trialForm.ihc=parts[1]||'';}const region=document.getElementById('trialRegion');if(region)trialForm.region=region.value;toast('检索条件已暂存在本次原型会话；尚未发起查询。');},
    draftSearch(){this.saveCriteria();const terms=[trialForm.histology,trialForm.differentiation,trialForm.ki67,trialForm.ihc,trialForm.genes,trialForm.treatment].filter(Boolean).join('；');const target=document.getElementById('queryFeedback');target.innerHTML=`<strong>检索词草稿已整理 · 未发送</strong><span>${esc(terms)}。数据源未接入，当前不会发起查询。</span>`;},
    query(){this.saveCriteria();const attemptedAt=new Date().toLocaleString('zh-CN',{hour12:false});const target=document.getElementById('queryFeedback');target.innerHTML=`<strong>未能查询 · 来源未接入</strong><span>尝试时间：${esc(attemptedAt)}。本地 SQLite 未加载，外部工具未连接；这不是“查询后零结果”。</span>`;const result=document.getElementById('trialResultsState');if(result)result.innerHTML=`<span>!</span><strong>未能查询 · ${esc(attemptedAt)}</strong><p>来源未接入，没有可核对的检索结果；不得据此判断无试验或不适合。</p>`;trialView='trialAssist';setPage('trials');}
  };
  function chartRow(m){return `<div class="chart-row"><div><strong>${esc(m.name)}</strong><small>${esc(m.unit)} · ${esc(m.reference)}</small></div>${svg(m)}<div class="chart-latest"><strong>${esc(m.latest)}</strong><small>${esc(m.unit)} · ${esc(m.date)}</small></div></div>`}
  const actions={
    pickMetrics:()=>openPicker(), addRecord:()=>toast('原型交互：打开“整理检查报告”候选流程（未保存模拟数据）。'),draft:()=>toast('已展示模拟的待核对草稿；确认前不会保存。'),edit:()=>toast('手工编辑入口为原型占位，正式版本待 G2/G3 后实现。'),addInjection:()=>toast('记录注射：原型表单占位（药物 / 剂量 / 日期 / 部位）。'),prrt:()=>toast('PRRT 周期档案为二期候选；当前只展示字段结构。'),match:()=>toast('当前本地库与外部来源均未接入；没有发起查询，状态仍为“未查过”。'),addSymptom:()=>toast('症状记录原型：患者自述，不做病因判断。'),addMood:()=>toast('心情记录原型：仅本地模拟，不保存。'),moodChoice:e=>toast(`已选“${e.textContent}”（模拟）。`),addQuestion:()=>toast('添加问题表单为原型占位。'),draftQuestion:()=>toast('已生成 2 条模拟问题草稿，请逐条核对后使用。'),editQuestion:()=>toast('问题编辑为原型占位。'),exportQuestions:()=>toast('就诊问题清单导出为原型占位。'),export:()=>toast('导出预览为原型占位；没有真实患者数据。'),correct:()=>toast('“改这一条”会建立更正版本；本原型未连接数据层。'),print:()=>window.print(),folder:()=>toast('原型不会打开真实目录选择器。'),parseMode:()=>toast('原型不收集凭据或上传文件。'),saveSettings:()=>toast('模拟设置已暂存（刷新后重置）。'),cancelSettings:()=>setPage('dashboard')
  };
  const pageDiscussion={dashboard:'请结合当前看板中已记录的近期指标、下次注射与复查安排，帮我整理需要核对的问题。只引用已记录内容，指出缺项，不作诊断或治疗建议。',records:'请协助整理本页模拟病理、化验和影像资料的核对清单。不要补全缺失事实，不把未核对内容当成已确认。',profile:'请帮我解释本页病理/IHC/基因档案中的术语并整理待核对问题。保留报告原文，不计算分级或判断风险。',metrics:'请按当前页面选中的指标系列和时间范围，帮我整理数值、单位、日期、可比性限制与待核对来源。不要将不同指标互相比较或作病情判断。',onechart:'请讨论当前一图秀所选指标与时间范围。仅整理可见数值、单位、日期、来源和不同指标不可比的限制；不要推断病情。',injection:'请根据当前治疗历程模拟记录，帮我整理注射日期、方案原文和待核对问题。不提供用药建议。',trials:'请检查本页档案字段准备度和数据源状态。当前本地库与外部工具未接入、没有发起查询；请勿生成试验条目、匹配分数或入组判断，只整理缺项与待连接来源。',nutrition:'请把本页患者自述的饮食/排便记录整理成复诊可讨论的问题，不判断病因或给饮食处方。',wellbeing:'请帮我整理本页情绪/生活记录中患者明确选择分享的内容，先确认隐私边界，不诊断。',questions:'请协助整理当前就诊问题草稿，保留患者原意，标出资料缺项，不自动添加未确认事实。',saved:'请根据本页可见的非私密收藏与记录，整理一份复诊回顾提纲；不要把收藏内容视为医学结论。',settings:'请解释本页设置项的用途与状态。不要包含本机路径、凭据或未验证数据。'};
  function discussionContext(){
    const metricLines=metricEntries.filter(m=>chartState.selected.has(m.id)).map(m=>`${m.short}: ${m.latest} ${m.unit} (${m.date}; 模拟值; 来源 ${m.sources?.at(-1)||m.source||'模拟报告'})`).join('\n');
    const pageFacts={
      dashboard:`病程：${data.profile.subtype}；报告原文分级：${data.profile.grade}；下一次注射：${data.next[0].value}，${data.next[0].date}；复查计划：${data.next[1].value}，${data.next[1].date}。`,
      records:'本页列出病理/IHC、化验和影像模拟资料；真实报告未导入。',
      profile:`病理模拟记录：${data.profile.grade}；Ki-67 ${data.profile.ki67}；原发部位 ${data.profile.primary}；基因项目状态仅为模拟占位。`,
      metrics:metricLines||'未选择或尚无指标记录。',
      onechart:`时间范围：${chartState.range}；所选指标：${metricLines||'无'}。不同指标不可互相比较。`,
      injection:`下一次注射模拟计划：${data.next[0].value}，${data.next[0].date}；治疗阶段见本页折叠卡。`,
      trials:'病理/IHC与治疗线仅为模拟字段；本地 SQLite 和外部来源均未接入，本次未查过，不代表没有试验。',
      nutrition:'本页没有已确认的患者症状记录；当前仅展示模拟记录入口。',
      wellbeing:'心情/心理内容默认视为私密，本讨论草稿不带入私密记录。',
      questions:'页面显示的问题为模拟问题草稿，尚未作为患者确认事项。',
      saved:'页面显示最近整理条目为模拟数据；不含私密记录。',
      settings:'设置页仅显示模拟状态，不含本机路径或凭据。'
    };
    return `[页面：${navItems.find(item=>item[0]===currentPage)?.[2]||'设置'}]\n${pageFacts[currentPage]||'当前页暂无可带入的已确认事实。'}\n核对状态：以上均为演示模拟数据，不等于医学审核。\n缺项：真实资料来源、真实患者确认记录均未提供。`;
  }
  function discussCurrentPage(){const prompt=pageDiscussion[currentPage]||'请围绕当前页面可见信息提出核对问题，不补充未记录事实。';const context=discussionContext();const payload={type:'neuroendocrine:agent-draft',prompt:`${prompt}\n\n${context}`,send:true};const pane=document.getElementById('agentPane');const input=document.getElementById('agentInput');const contextLabel=document.getElementById('agentContextLabel');const state=document.getElementById('agentHostState');if(window.parent!==window){window.parent.postMessage(payload,location.origin);state.textContent='已请求原生 AI 对话 · 宿主确认状态';pane.hidden=false;syncAgentToggle();return;}pane.hidden=false;syncAgentToggle();input.value=payload.prompt;contextLabel.textContent=`当前页面：${navItems.find(item=>item[0]===currentPage)?.[2]||'设置'} · 宿主模拟`;document.getElementById('agentDraftStatus').textContent='本地原型草稿 · 未发送 · 非真实 DSH 会话';input.focus();}
  function syncAgentToggle(){const pane=document.getElementById('agentPane'),button=document.getElementById('toggleAgent'),label=document.getElementById('agentToggleLabel');button.setAttribute('aria-expanded',String(!pane.hidden));label.textContent=pane.hidden?'打开 AI 对话':'收起 AI 对话';}
  function toggleAgentPane(){const pane=document.getElementById('agentPane');pane.hidden=!pane.hidden;syncAgentToggle();}
  function toast(text){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.append(t);}t.textContent=text;t.classList.add('visible');clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>t.classList.remove('visible'),2800);}
  function openPicker(){const dialog=document.getElementById('metricPicker'), opts=document.getElementById('metricOptions');const selected=new Set([...document.querySelectorAll('[data-chart-id]')].map(x=>x.dataset.chartId));opts.innerHTML=data.metricSeries.map(s=>`<fieldset><legend>${s.title}</legend>${s.metrics.map(m=>`<label class="metric-option"><input type="checkbox" value="${m.id}" ${selected.has(m.id)?'checked':''}><span><strong>${m.name}</strong><small>${m.latest} ${m.unit} · ${m.date}</small></span></label>`).join('')}</fieldset>`).join('');const checks=[...opts.querySelectorAll('input[type=checkbox]')];const limit=()=>{const marked=checks.filter(x=>x.checked);checks.forEach(x=>{x.disabled=!x.checked&&marked.length>=4;});let hint=opts.querySelector('.picker-limit');if(!hint){hint=document.createElement('p');hint.className='picker-limit';opts.prepend(hint);}hint.textContent=`最多同时选择 4 项（已选 ${marked.length} 项）`;};checks.forEach(x=>x.addEventListener('change',limit));limit();dialog.showModal();document.getElementById('applyMetrics').onclick=(e)=>{e.preventDefault();const ids=[...opts.querySelectorAll('input:checked')].map(x=>x.value);if(!ids.length){toast('至少选择一项指标。');return;}const picked=data.metricSeries.flatMap(s=>s.metrics).filter(m=>ids.includes(m.id));document.getElementById('oneChartList').innerHTML=picked.length?picked.map(m=>`<div data-chart-id="${m.id}">${chartRow(m)}</div>`).join(''):'<p class="empty-state">这个时间窗里没有所选指标。请扩大时间范围或重新选择指标。</p>';document.getElementById('chartSubtitle').textContent=`已选 ${picked.length} 项指标 · 模拟数据`;dialog.close();};}
  document.querySelectorAll('.flip-btn').forEach(()=>{});
  document.addEventListener('click',e=>{const btn=e.target.closest('.metric-card-inner');if(btn){const card=btn.closest('.metric-card');const flipped=card.classList.toggle('flipped');btn.setAttribute('aria-pressed',String(flipped));}});
  document.querySelectorAll('.suggestion').forEach(s=>s.addEventListener('click',()=>{document.getElementById('agentInput').value=s.dataset.prompt;document.getElementById('agentInput').focus();}));
  document.getElementById('toggleAgent').addEventListener('click',toggleAgentPane);
  document.getElementById('sendAgent').addEventListener('click',()=>{const input=document.getElementById('agentInput');if(!input.value.trim())return;if(window.parent!==window){window.parent.postMessage({type:'neuroendocrine:agent-draft',prompt:input.value,send:true},location.origin);document.getElementById('agentDraftStatus').textContent='已请求原生会话发送 · 等待宿主确认';}else{toast('本地原型未接通 DSH 原生会话；草稿未发送。');}});
  window.addEventListener('message',event=>{if(event.source!==window.parent||event.origin!==location.origin)return;if(event.data?.type==='neuroendocrine:agent-draft-status'){document.getElementById('agentHostState').textContent=event.data.status==='ready'?'原生 AI 对话已连接':'原生 AI 对话暂不可用';}});
  window.addEventListener('beforeprint',()=>document.querySelectorAll('details.phase-fold').forEach(d=>{d.dataset.wasOpen=d.open?'1':'0';d.open=true;}));
  window.addEventListener('afterprint',()=>document.querySelectorAll('details.phase-fold').forEach(d=>{d.open=d.dataset.wasOpen==='1';delete d.dataset.wasOpen;}));
  window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(pages[id]&&id!==currentPage)setPage(id);});
  setPage(pages[location.hash.slice(1)]?location.hash.slice(1):'dashboard');
})();
